        && trackTotalHitsUpTo != SearchContext.TRACK_TOTAL_HITS_DISABLED) {
            throw new IllegalArgumentException(
                "["
                    + TOTAL_HITS_AS_INT_PARAM
                    + "] cannot be used "
                    + "if the tracking of total hits is not accurate, got "
                    + trackTotalHitsUpTo
            );
        }
}

